#include "CloseToHSL/Core/Runtime/Domains/SecureCompute/Policies/ExecutionState/PrivilegedExecutionStateOwnerPolicy.h"
#include <cassert>
using namespace YAKSys_Hybrid_CPU::Core;
int main(){ auto policy=PrivilegedExecutionStateOwnerPolicy::getDefault(); auto check=[&](unsigned long long cr0,unsigned long long epoch){ auto d=std::make_shared<PrivilegedExecutionStateDescriptor>(PrivilegedExecutionStateDescriptor{1,2,{3},true,{PrivilegedControlRegisterKind::GuestCr0,cr0},{PrivilegedControlRegisterKind::GuestCr4,2},{3,1,3,2,true},PrivilegedExecutionStateEvidenceClass::GuestVisibleReadOnlyProjection,PrivilegedExecutionStateMigrationClass::RevalidatedAfterRestore}); return policy->Admit(std::make_shared<PrivilegedExecutionStateOwnerRequest>(d,1,2,PrivilegedExecutionStateEpoch{epoch})); }; auto r=check(1,3); assert(r->IsAllowed && !r->ReadOnlyProjectionAuthorized && !r->MutationAuthorized && !r->BackendExecutionAuthorized && !r->CompletionPublicationAuthorized && !r->RetirePublicationAuthorized); assert(check(1,4)->Decision==PrivilegedExecutionStateOwnerDecision::DeniedStaleEpoch); assert(check(4,3)->Decision==PrivilegedExecutionStateOwnerDecision::DeniedGuestCr0ReservedBits); assert(check(0,3)->Decision==PrivilegedExecutionStateOwnerDecision::DeniedGuestCr0RequiredBits); }
